use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::PathBuf;

use anyhow::{bail, Context, Result};
use unicodex_core::{validate_cid, ObjectStore};

const ISSUED: &[u8] = b"local_explicit_benchmark_job_dispatch_issuance.v1\n";
const CONSUMED: &[u8] = b"consumed_before_remote_benchmark_job_network.v1\n";

pub(super) fn issue(store: &ObjectStore, cid: &str) -> Result<()> {
    create(store, "issued", cid, ISSUED)
}

pub(super) fn verify_issued(store: &ObjectStore, cid: &str) -> Result<()> {
    if fs::read(path(store, "issued", cid)?)? != ISSUED {
        bail!("benchmark job dispatch local issuance marker is invalid");
    }
    Ok(())
}

pub(super) fn consume(store: &ObjectStore, cid: &str) -> Result<()> {
    verify_issued(store, cid)?;
    create(store, "consumed", cid, CONSUMED)
        .context("benchmark job dispatch authorization was already consumed")
}

pub(super) fn consumed(store: &ObjectStore, cid: &str) -> Result<bool> {
    match fs::read(path(store, "consumed", cid)?) {
        Ok(bytes) if bytes == CONSUMED => Ok(true),
        Ok(_) => bail!("benchmark job dispatch consumption marker is invalid"),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(error.into()),
    }
}

fn create(store: &ObjectStore, state: &str, cid: &str, marker: &[u8]) -> Result<()> {
    let path = path(store, state, cid)?;
    fs::create_dir_all(
        path.parent()
            .context("dispatch state directory is missing")?,
    )?;
    let mut file = OpenOptions::new().write(true).create_new(true).open(path)?;
    file.write_all(marker)?;
    file.sync_all()?;
    Ok(())
}

fn path(store: &ObjectStore, state: &str, cid: &str) -> Result<PathBuf> {
    validate_cid(cid)?;
    Ok(store
        .objects_dir()
        .parent()
        .context("object store base directory is missing")?
        .join("foreign-process")
        .join("benchmark-job-dispatch-authorizations")
        .join("v1")
        .join(state)
        .join(cid))
}

